/**
 * Old <-> new company slug equivalence (src/data/slug-renames.json, generated by
 * scripts/weekly/slug_renames.py). Denylist, exclusion and hold keys keep their
 * written form; lookups go through slugEquivalents() so a key matches the company
 * both before and after a catalog rebuild moves it to its canonical slug.
 */
import slugRenames from "../data/slug-renames.json" with { type: "json" };

const FORWARD: Record<string, string> = slugRenames.renames;
const BACK: Record<string, string> = Object.fromEntries(Object.entries(FORWARD).map(([o, n]) => [n, o]));

export function slugEquivalents(slug: string): string[] {
  const s = slug.trim().toLowerCase();
  if (!s) return [];
  const out = [s];
  for (const other of [FORWARD[s], BACK[s]]) if (other && !out.includes(other)) out.push(other);
  return out;
}

/** True when any equivalent of `slug` is in `keys`. */
export function hasSlugKey(keys: { has(k: string): boolean }, slug: string): boolean {
  return slugEquivalents(slug).some((k) => keys.has(k));
}
